import pandas as pd

def clean(df):
    df = df.copy()
    # Remove exact duplicate rows so they don't inflate the average
    df = df.drop_duplicates().reset_index(drop=True)
    return df

def answer(df):
    df = df.dropna(subset=['Category'])
    result = {}
    grouped = df.groupby('Category')['Price'].mean()
    for category, value in grouped.items():
        result[category] = float(value)
    return result
